53	        ".sidebar-icon-collapsed"
54	      );
55	
56	      if (sidebar.classList.contains("collapsed")) {
57	        expandedIcon.classList.add("hidden");
58	        collapsedIcon.classList.remove("hidden");
59	        sidebarToggleBtn.querySelector(".sidebar-chevron").style.transform =
60	          "rotate(180deg)";
61	      } else {
62	        expandedIcon.classList.remove("hidden");
63	        collapsedIcon.classList.add("hidden");
64	        sidebarToggleBtn.querySelector(".sidebar-chevron").style.transform =
65	          "rotate(0deg)";
66	      }
67	    });
68	  }
69	
70	  const resizer = document.getElementById("sidebar-resizer");
71	  const sidebar = document.querySelector(".sidebar");
72	  if (resizer && sidebar) {
73	    let isResizing = false;
74	
75	    resizer.addEventListener("mousedown", (e) => {
76	      isResizing = true;
77	      document.body.style.cursor = "col-resize";
78	      sidebar.style.transition = "none";
79	      resizer.classList.add("resizing");
80	      // Prevent text selection while dragging
81	      document.body.style.userSelect = "none";
82	    });
83	
84	    document.addEventListener("mousemove", (e) => {
85	      if (!isResizing) return;
86	      let newWidth = e.clientX;
87	      if (newWidth < 200) newWidth = 200;
88	      if (newWidth > 800) newWidth = 800;
89	      document.documentElement.style.setProperty(
90	        "--sidebar-width",
91	        `${newWidth}px`
92	      );
93	    });
94	
95	    document.addEventListener("mouseup", () => {
96	      if (isResizing) {
97	        isResizing = false;
98	        document.body.style.cursor = "default";
99	        sidebar.style.transition =
100	          "margin-left 0.3s cubic-bezier(0.4, 0, 0.2, 1)";
101	        resizer.classList.remove("resizing");
102	        document.body.style.userSelect = "";
103	      }
104	    });
105	  }
106	
107	  loadConversations();
108	
109	  flavorSelect.addEventListener("change", () => {
110	    localStorage.setItem("agy-flavor", flavorSelect.value);
111	    loadConversations();
112	    document.getElementById("transcript-container").innerHTML =
113	      '<div class="empty-state">Select a session from the sidebar to view its transcript.</div>';
114	    const statsContainer = document.getElementById("session-stats-container");
115	    if (statsContainer) statsContainer.innerHTML = "";
116	    document.getElementById("current-session-title").innerText =
117	      "Select a session";
118	    document.getElementById("current-session-id").innerText = "";
119	    document.getElementById("summarize-btn").disabled = true;
120	    document.getElementById("ai-summary-container").classList.add("hidden");
121	  });
122	
123	  const summaryHeader = document.getElementById("ai-summary-header");
124	  if (summaryHeader) {
125	    summaryHeader.addEventListener("click", () => {
126	      const content = document.getElementById("ai-summary-content");
127	      const chevron = summaryHeader.querySelector(".chevron");
128	      content.classList.toggle("collapsed");
129	      if (content.classList.contains("collapsed")) {
130	        chevron.style.transform = "rotate(0deg)";
131	      } else {
132	        chevron.style.transform = "rotate(90deg)";
133	      }
134	    });
135	  }
136	
137	  document
138	    .getElementById("summarize-btn")
