222	export function filterAndSortConversations(
223	  conversations,
224	  searchTerm,
225	  descending
226	) {
227	  let filtered = [...conversations];
228	  const term = (searchTerm || "").toLowerCase();
229	  if (term) {
230	    filtered = filtered.filter(
231	      (c) =>
232	        c.summary.toLowerCase().includes(term) ||
233	        c.id.toLowerCase().includes(term)
234	    );
235	  }
236	  if (!descending) {
237	    filtered.reverse();
238	  }
239	  return filtered;
240	}
241	
242	export async function loadConversations() {
243	  const list = document.getElementById("conversations-list");
244	  const flavor = encodeURIComponent(
245	    document.getElementById("flavor-select").value
246	  );
247	  try {
248	    const res = await fetch(
249	      `/api/brain/conversations?flavor=${flavor}&limit=${CONV_PAGE_SIZE}&offset=0`
250	    );
251	    if (!res.ok) throw new Error(`HTTP ${res.status}`);
252	    const page = await res.json();
253	    allConversations = page.items || [];
254	    convTotal = page.total ?? allConversations.length;
255	    announceConversations();
256	    // Only the first load auto-selects (deep-link or newest session); re-renders must not.
257	    renderConversationsList(true);
258	    // A reachable-but-empty store is the first-run case: guide the user to import instead of
259	    // leaving the main pane on the "select a session" prompt when there are none to select.
260	    if (convTotal === 0) showEmptyStoreOnboarding();
261	  } catch (e) {
262	    list.innerHTML =
263	      '<div class="loading-state" style="padding:16px;">Error loading sessions. Is the backend running?</div>';
264	  }
265	}
266	
267	// The human-readable label of the selected source, e.g. "OpenAI Codex".
268	function sourceLabel() {
269	  const sel = document.getElementById("flavor-select");
270	  return sel?.selectedOptions?.[0]?.text?.trim() || "agent";
271	}
272	
273	// Writes a message to the sidebar's polite live region (screen-reader announcement).
274	function announce(message) {
275	  const status = document.getElementById("conv-status");
276	  if (status) status.textContent = message;
277	}
278	
279	// Guidance shown in the main pane when the selected source has no sessions yet. Scoped to the source
280	// (the picker has no "all" option), so it reads correctly whether this is a true first run or just a
281	// source the user hasn't imported.
282	function showEmptyStoreOnboarding() {
283	  const container = document.getElementById("transcript-container");
284	  if (!container) return;
285	  const source = escapeHtml(sourceLabel());
286	  const cmd = `agent-ingest --server ${window.location.origin}`;
287	  container.innerHTML = `
288	    <div class="empty-state">
289	      <div class="empty-icon" aria-hidden="true">📭</div>
290	      <h2>No ${source} sessions yet</h2>
291	      <p>Run the <strong>agent-ingest</strong> CLI on a machine that has ${source} sessions — it
292	        scans for Antigravity, OpenAI Codex, and Claude Code transcripts and pushes them here.</p>
293	      <div class="onboarding-cmd-row">
294	        <pre class="onboarding-cmd">${escapeHtml(cmd)}</pre>
295	        <button type="button" class="onboarding-copy" id="onboarding-copy">Copy</button>
296	      </div>
297	      <p>Run it again any time (or on a schedule) — it only uploads what changed.</p>
298	    </div>`;
299	
300	  const copyBtn = document.getElementById("onboarding-copy");
301	  copyBtn?.addEventListener("click", async () => {
302	    try {
303	      await navigator.clipboard.writeText(cmd);
304	      copyBtn.textContent = "Copied";
305	      announce("Command copied to clipboard.");
306	    } catch {
307	      announce("Copy failed — select the command and copy it manually.");
308	    }
309	  });
310	
311	  // The header prompts "Select a session", which makes no sense with none to select.
312	  const title = document.getElementById("current-session-title");
313	  if (title) title.textContent = "Getting started";
314	}
315	
316	// Appends the next page to what's already loaded. The offset is the count we hold; on a stable list
317	// pages don't overlap, but if sessions are ingested while browsing, offset paging can repeat or skip
318	// a row at the boundary (an accepted trade-off for a sidebar — re-open the flavor to refresh).
319	export async function loadMoreConversations() {
320	  const flavor = encodeURIComponent(
321	    document.getElementById("flavor-select").value
322	  );
323	  const btn = document.getElementById("load-more-btn");
324	  if (btn) {
325	    btn.disabled = true;
326	    btn.textContent = "Loading…";
327	  }
328	  try {
329	    const res = await fetch(
330	      `/api/brain/conversations?flavor=${flavor}&limit=${CONV_PAGE_SIZE}&offset=${allConversations.length}`
331	    );
332	    if (!res.ok) throw new Error(`HTTP ${res.status}`);
333	    const page = await res.json();
334	    allConversations = allConversations.concat(page.items || []);
335	    convTotal = page.total ?? convTotal;
336	    announceConversations();
337	    renderConversationsList();
338	    // Keep the keyboard user on the control they just used (the button is rebuilt each render).
339	    document.getElementById("load-more-btn")?.focus();
340	  } catch (e) {
341	    if (btn) {
342	      btn.disabled = false;
343	      btn.textContent = "Load more";
344	    }
345	  }
346	}
347	
348	// Announces the loaded/total count on a polite live region, so a screen-reader user hears that more
349	// sessions arrived. Kept separate from the list so re-rendering rows doesn't spam the reader.
350	function announceConversations() {
351	  const status = document.getElementById("conv-status");
352	  if (status) {
353	    status.textContent =
354	      convTotal > allConversations.length
355	        ? `Loaded ${allConversations.length} of ${convTotal} sessions.`
356	        : `Loaded all ${allConversations.length} sessions.`;
357	  }
358	}
359	
360	export function renderConversationsList(autoSelect = false) {
361	  const list = document.getElementById("conversations-list");
362	  // A re-render (search, sort, "Load more") rebuilds the list; keep the user's scroll position rather
363	  // than jumping them back to the top.
364	  const prevScroll = list.scrollTop;
365	  list.innerHTML = "";
366	
367	  const searchTerm =
368	    document.getElementById("conversation-search")?.value || "";
369	  const filtered = filterAndSortConversations(
370	    allConversations,
371	    searchTerm,
372	    sortDescending
373	  );
374	
375	  if (filtered.length === 0) {
376	    const empty = document.createElement("div");
377	    empty.className = "loading-state";
378	    // Three empty cases: a genuinely empty source (first run — wins even mid-search, since there's
379	    // nothing to search); an active search with more pages to pull; and a search that matched
380	    // nothing in a non-empty source.
381	    if (convTotal === 0) {
382	      empty.textContent = `No ${sourceLabel()} sessions yet — import with agent-ingest.`;
383	    } else if (searchTerm && allConversations.length < convTotal) {
384	      empty.textContent =
385	        "No matches in the loaded sessions — load more to keep searching.";
386	    } else {
387	      empty.textContent = "No sessions found";
388	    }
389	    list.appendChild(empty);
390	  } else {
391	    filtered.forEach((conv) => {
392	      const div = document.createElement("div");
393	      div.className = "conv-item";
394	      div.dataset.id = conv.id;
395	      div.dataset.summary = conv.summary;
396	      div.dataset.updatedAt = conv.updatedAt || "0";
397	      div.innerHTML = `<div class="conv-id">${escapeHtml(conv.summary)}</div>`;
398	      list.appendChild(div);
399	    });
400	  }
401	
402	  appendLoadMore(list);
403	
404	  // Event Delegation for conversation selection
405	  if (!list.dataset.listenerAttached) {
406	    list.addEventListener("click", (e) => {
407	      const item = e.target.closest(".conv-item");
408	      if (item && item.dataset.id) {
409	        selectConversation(item.dataset.id, item);
410	      }
411	    });
412	
413	    // Custom Popover Logic
414	    const popover = document.getElementById("conv-popover");
415	    list.addEventListener("mouseover", (e) => {
416	      const item = e.target.closest(".conv-item");
417	      if (item && item.dataset.id && popover) {
418	        document.getElementById("popover-title").innerText =
419	          item.dataset.summary;
420	        document.getElementById("popover-id").innerText = item.dataset.id;
421	
422	        const timestamp = parseInt(item.dataset.updatedAt, 10);
423	        let timeStr = "Unknown time";
424	        if (timestamp > 0) {
425	          const d = new Date(timestamp);
426	          const dateText = d.toLocaleDateString("en-US", {
427	            year: "numeric",
428	            month: "long",
429	            day: "numeric",
430	          });
431	
432	          const diffMs = Date.now() - timestamp;
433	          const diffMin = Math.floor(diffMs / (1000 * 60));
434	          const diffHour = Math.floor(diffMs / (1000 * 60 * 60));
435	          const diffDay = Math.floor(diffMs / (1000 * 60 * 60 * 24));
436	
437	          let relStr;
438	          if (diffDay > 0)
439	            relStr = diffDay === 1 ? "1 day ago" : `${diffDay} days ago`;
440	          else if (diffHour > 0)
441	            relStr = diffHour === 1 ? "1 hour ago" : `${diffHour} hours ago`;
442	          else if (diffMin > 0)
443	            relStr = diffMin === 1 ? "1 minute ago" : `${diffMin} minutes ago`;
444	          else relStr = "just now";
445	
446	          timeStr = `${dateText} (${relStr})`;
447	        }
448	        document.getElementById("popover-time").innerHTML = timeStr;
449	
450	        popover.classList.remove("hidden");
451	      }
452	    });
453	
454	    list.addEventListener("mousemove", (e) => {
455	      const item = e.target.closest(".conv-item");
456	      if (item && popover && !popover.classList.contains("hidden")) {
457	        let top = e.clientY + 15;
458	        let left = e.clientX + 15;
459	
460	        // Prevent overflow off bottom/right edges
461	        if (top + popover.offsetHeight > window.innerHeight) {
462	          top = e.clientY - popover.offsetHeight - 15;
463	        }
464	        if (left + popover.offsetWidth > window.innerWidth) {
465	          left = e.clientX - popover.offsetWidth - 15;
466	        }
467	
468	        popover.style.top = `${top}px`;
469	        popover.style.left = `${left}px`;
470	      }
471	    });
472	
473	    list.addEventListener("mouseout", (e) => {
474	      const item = e.target.closest(".conv-item");
475	      if (item && popover) {
476	        if (e.relatedTarget && item.contains(e.relatedTarget)) return;
477	        popover.classList.add("hidden");
478	      }
479	    });
480	
481	    list.dataset.listenerAttached = "true";
482	  }
483	
484	  const hashId = window.location.hash.substring(1);
485	
486	  if (autoSelect) {
487	    // Initial load only: open the deep-linked session, or the newest one.
488	    const targetDiv = hashId
489	      ? list.querySelector(`[data-id="${hashId}"]`)
490	      : list.firstElementChild;
491	    if (targetDiv) {
492	      targetDiv.click();
493	    }
494	  } else if (hashId) {
495	    // A re-render must not re-open (and reload) the current session — just restore its highlight.
496	    list
497	      .querySelector(`.conv-item[data-id="${hashId}"]`)
498	      ?.classList.add("active");
499	  }
500	
501	  list.scrollTop = prevScroll;
502	}
503	
504	// Appends a "Load more" control when the store holds more sessions than are loaded. Rebuilt on every
505	// render (the list is cleared each time), so its count stays in step with what's loaded.
506	function appendLoadMore(list) {
507	  if (allConversations.length >= convTotal) return;
508	  const footer = document.createElement("div");
509	  footer.className = "conv-loadmore";
510	  const btn = document.createElement("button");
511	  btn.id = "load-more-btn";
512	  btn.className = "load-more-btn";
513	  // "loaded" makes clear the count is how many are held locally, not how many matched a search.
514	  btn.textContent = `Load more (${allConversations.length} of ${convTotal} loaded)`;
515	  btn.addEventListener("click", () => loadMoreConversations());
516	  footer.appendChild(btn);
517	  list.appendChild(footer);
518	}
519	
520	export async function selectConversation(id, element) {
521	  document
522	    .querySelectorAll(".conv-item")
523	    .forEach((el) => el.classList.remove("active"));
524	  element.classList.add("active");
525	
526	  // Update URL hash
527	  window.location.hash = id;
528	
529	  const title = document.getElementById("current-session-title");
530	  title.innerText = element.querySelector(".conv-id").innerText;
531	
532	  const subtitle = document.getElementById("current-session-id");
533	  subtitle.innerText = id;
534	  subtitle.dataset.id = id;
535	
536	  document.getElementById("summarize-btn").disabled = false;
537	
538	  // Auto trigger analysis
539	  triggerAnalysis(id, false);
540	
541	  const container = document.getElementById("transcript-container");
542	  container.innerHTML =
543	    '<div class="loading-state" style="text-align:center; padding: 40px; color:#94a3b8;">Loading transcript...</div>';
544	
545	  try {
546	    const flavor = encodeURIComponent(
547	      document.getElementById("flavor-select").value
548	    );
549	    const response = await fetch(
550	      `/api/brain/conversations/${id}/transcript?flavor=${flavor}`
551	    );
552	    const steps = await response.json();
553	
554	    state.spansMultipleDays = false;
555	    if (
556	      steps &&
557	      steps.length > 0 &&
558	      steps[0].created_at &&
559	      steps[steps.length - 1].created_at
560	    ) {
561	      const firstDateStr = new Date(steps[0].created_at).toLocaleDateString();
562	      const lastDateStr = new Date(
563	        steps[steps.length - 1].created_at
564	      ).toLocaleDateString();
565	      if (firstDateStr !== lastDateStr) {
566	        state.spansMultipleDays = true;
567	      }
568	    }
569	
570	    renderTranscript(steps, container);
571	    renderStats(steps);
572	  } catch (e) {
573	    container.innerHTML =
574	      '<div class="loading-state" style="text-align:center; color:red;">Failed to load transcript.</div>';
575	  }
576	}
