16	import { escapeHtml, formatTime, apiFetch } from "./utils.js";
17	
18	const SUPPORTED_HIGHLIGHT_EXTS = [
19	  "js",
20	  "json",
21	  "java",
22	  "html",
23	  "css",
24	  "md",
25	  "sh",
26	  "bash",
27	  "yaml",
28	  "yml",
29	  "xml",
30	  "sql",
31	  "kt",
32	  "kts",
33	  "gradle",
34	  "properties",
35	  "py",
36	  "go",
37	  "rs",
38	  "cpp",
39	  "c",
40	  "ts",
41	  "jsx",
42	  "tsx",
43	];
44	
45	// Map a file path to a highlight.js language class, or "" when the extension is unsupported.
46	export function languageClassFor(path) {
47	  const ext = path.split(".").pop().toLowerCase();
48	  return SUPPORTED_HIGHLIGHT_EXTS.includes(ext) ? `language-${ext}` : "";
49	}
50	
51	// Extract the filesystem path from a file:// href (strips the scheme, any line-number hash, and
52	// percent-encoding).
53	export function pathFromFileLink(href) {
54	  let path = href.replace("file://", "");
55	  path = path.split("#")[0];
56	  return decodeURIComponent(path);
57	}
58	
59	// Fetch a file from the backend and render it in the preview modal. On failure, alerts the user.
60	export async function openFilePreview(path) {
61	  const modal = document.getElementById("file-modal");
62	  const modalTitle = document.getElementById("file-modal-title");
63	  const modalContent = document.getElementById("file-modal-content");
64	
65	  try {
66	    const res = await apiFetch(
67	      `/api/brain/file?path=${encodeURIComponent(path)}`
68	    );
69	    if (!res.ok) {
70	      if (res.status === 404) throw new Error("File not found");
71	      throw new Error("Failed to load file");
72	    }
73	    const content = await res.text();
74	
75	    modalTitle.innerText = path;
76	
77	    const langClass = languageClassFor(path);
78	    modalContent.className = langClass;
79	    modalContent.innerHTML = escapeHtml(content);
80	
81	    if (langClass && window.hljs) {
82	      delete modalContent.dataset.highlighted;
83	      hljs.highlightElement(modalContent);
84	    }
85	
86	    modal.classList.remove("hidden");
87	  } catch (err) {
88	    alert(err.message + ":\n" + path);
89	  }
90	}
91	
92	export function closeFileModal() {
93	  const modal = document.getElementById("file-modal");
94	  if (modal) modal.classList.add("hidden");
95	}
96	
97	export function initUI() {
98	  const modal = document.getElementById("file-modal");
99	  const closeBtn = document.getElementById("close-modal-btn");
100	
101	  if (closeBtn) {
102	    closeBtn.addEventListener("click", () => {
103	      closeFileModal();
104	    });
105	  }
106	
107	  if (modal) {
108	    modal.addEventListener("click", (e) => {
109	      if (e.target === modal) {
110	        closeFileModal();
111	      }
112	    });
113	  }
114	
115	  // Intercept file:// links using event delegation
116	  document.addEventListener("click", async (e) => {
117	    const link = e.target.closest("a");
118	    if (link && link.href && link.href.startsWith("file://")) {
119	      e.preventDefault();
120	      await openFilePreview(pathFromFileLink(link.href));
121	    }
122	  });
123	
124	  document.addEventListener("keydown", (e) => {
125	    if (e.key === "Escape" && modal && !modal.classList.contains("hidden")) {
126	      closeFileModal();
127	    }
128	  });
129	
130	  initScrubber();
131	}
132	
133	function initScrubber() {
134	  const track = document.getElementById("timeline-track");
135	  if (!track) return;
136	  const thumb = document.getElementById("timeline-thumb");
137	  const label = document.getElementById("timeline-label");
138	  const scrollContainer = document.getElementById("transcript-container");
139	
140	  if (!scrollContainer) return;
141	
142	  let isDragging = false;
143	  let isTicking = false;
144	
145	  // Use IntersectionObserver to update label efficiently without getBoundingClientRect
146	  let visibleCards = new Set();
147	
148	  const updateTimelineRect = () => {
149	    if (window.timelineTotalMs > 0 && visibleCards.size > 0) {
150	      let minTs = Infinity;
151	      let maxTs = -Infinity;
152	      visibleCards.forEach((el) => {
153	        if (el.dataset.timestampStart && el.dataset.timestampEnd) {
154	          const start = parseInt(el.dataset.timestampStart, 10);
155	          const end = parseInt(el.dataset.timestampEnd, 10);
156	          if (start < minTs) minTs = start;
157	          if (end > maxTs) maxTs = end;
158	        } else if (el.dataset.timestamp) {
159	          const tsStart = parseInt(el.dataset.timestamp, 10);
160	          const tsEnd = el.dataset.timestampEnd
161	            ? parseInt(el.dataset.timestampEnd, 10)
162	            : tsStart;
163	          if (tsStart < minTs) minTs = tsStart;
164	          if (tsEnd > maxTs) maxTs = tsEnd;
165	        }
166	      });
167	
168	      if (minTs !== Infinity && maxTs !== -Infinity) {
169	        // Add a slight buffer to the width so it doesn't look like a 0px line for a single card
170	        const startPct =
171	          ((minTs - window.timelineStart) / window.timelineTotalMs) * 100;
172	        let widthPct = ((maxTs - minTs) / window.timelineTotalMs) * 100;
173	
174	        const indicator = document.getElementById("session-timeline-indicator");
175	        if (indicator) {
176	          const clampedStart = Math.max(0, Math.min(100, startPct));
177	          indicator.style.left = `calc(${clampedStart}% - ${
178	            (clampedStart / 100) * 2
179	          }px)`;
180	          indicator.style.width = widthPct + "%";
181	          indicator.style.minWidth = "2px";
182	          indicator.style.display = "block";
183	        }
184	      }
185	    }
186	  };
187	
188	  const labelObserver = new IntersectionObserver(
189	    (entries) => {
190	      entries.forEach((entry) => {
191	        if (entry.isIntersecting) {
192	          const card = entry.target;
193	          if (card.dataset.time) {
194	            label.innerText = card.dataset.time;
195	          }
196	        }
197	      });
198	    },
199	    {
200	      root: scrollContainer,
201	      rootMargin: "-10% 0px -80% 0px",
202	      threshold: 0,
203	    }
204	  );
205	
206	  const rectObserver = new IntersectionObserver(
207	    (entries) => {
208	      let changedVisibility = false;
209	      entries.forEach((entry) => {
210	        if (entry.isIntersecting) {
211	          visibleCards.add(entry.target);
212	          changedVisibility = true;
213	        } else {
