39	// Transcript content is untrusted (it is whatever the agent, the user, or a web page the agent read
40	// happened to produce), so every piece of it that becomes HTML must pass through DOMPurify. The
41	// default allowed URI schemes are extended with file:// — Antigravity transcripts link local files
42	// that way and the click is intercepted for the in-app preview modal.
43	const PURIFY_CONFIG = {
44	  ALLOWED_URI_REGEXP:
45	    /^(?:(?:https?|mailto|file):|[^a-z]|[a-z+.\-]+(?:[^a-z+.\-:]|$))/i,
46	};
47	
48	/** Renders untrusted markdown to sanitized HTML. The only safe way to innerHTML transcript text. */
49	export function renderMarkdown(text) {
50	  if (text == null) return "";
51	  return DOMPurify.sanitize(marked.parse(String(text)), PURIFY_CONFIG);
52	}
53	
54	/**
55	 * fetch() for the app's own API. When the server guards the API with API_TOKEN, the token the user
56	 * entered is attached as a bearer; on a 401 the user is prompted once and the request retried, so a
57	 * freshly guarded server asks for the token instead of silently failing.
58	 */
59	export async function apiFetch(url, options = {}) {
60	  // localStorage can be unavailable (private browsing, test environments); degrade to promptless.
61	  const storage = {
62	    get() {
63	      try {
64	        return localStorage.getItem("agy-api-token") || "";
65	      } catch {
66	        return "";
67	      }
68	    },
69	    set(value) {
70	      try {
71	        localStorage.setItem("agy-api-token", value);
72	      } catch {}
73	    },
74	  };
75	  const doFetch = (token) => {
76	    const headers = { ...(options.headers || {}) };
77	    if (token) headers["Authorization"] = `Bearer ${token}`;
78	    return fetch(url, { ...options, headers });
79	  };
80	  let response = await doFetch(storage.get());
81	  if (response.status === 401) {
82	    const entered = window.prompt(
83	      "This server requires an API token (API_TOKEN). Enter it to continue:"
84	    );
85	    if (entered && entered.trim()) {
86	      storage.set(entered.trim());
87	      response = await doFetch(entered.trim());
88	    }
89	  }
90	  return response;
91	}
