93	/** apiFetch that throws on a non-OK status and resolves to the parsed JSON body. */
94	export async function fetchJson(url, options) {
95	  const res = await apiFetch(url, options);
96	  if (!res.ok) throw new Error(`HTTP ${res.status}`);
97	  return res.json();
98	}
