100	export function escapeHtml(unsafe) {
101	  if (!unsafe) return "";
102	  return String(unsafe)
103	    .replace(/&/g, "&amp;")
104	    .replace(/</g, "&lt;")
105	    .replace(/>/g, "&gt;")
106	    .replace(/"/g, "&quot;")
107	    .replace(/'/g, "&#039;");
108	}
