110	/** A titled report section with a colored uppercase heading (shared by the report views). */
111	export function section(title, color, bodyHtml) {
112	  return `<div style="margin-top:28px;">
113	      <div style="font-size:0.75rem; font-weight:700; color:${color}; margin-bottom:16px; letter-spacing:0.05em; text-transform:uppercase;">${escapeHtml(
114	    title
115	  )}</div>
116	      ${bodyHtml}
117	    </div>`;
118	}
