126	 * Wires a non-<button> element to act like one: click plus Enter/Space activation. The caller is
127	 * responsible for making it focusable and announced (tabindex="0", role="button") in the markup.
128	 */
129	export function wireButton(el, handler) {
130	  el.addEventListener("click", handler);
131	  el.addEventListener("keydown", (e) => {
132	    if (e.key === "Enter" || e.key === " ") {
133	      e.preventDefault(); // Space must not scroll the page
