          created_at: "2026-06-19T10:00:05Z",
        },
        {
          type: "ERROR_MESSAGE",
          status: "ERROR",
          error: "NullPointerException",
          content: "Encountered error in step execution: NullPointerException",
          created_at: "2026-06-19T10:00:10Z",
