+            flat.append(breaksLine(c) ? ' ' : c);
+        }
+        String cleaned = UNTRUSTED_TAG_PATTERN
+            .matcher(flat)
+            .replaceAll("[marker removed]")
+            .replaceAll("\\s{2,}", " ")
+            .strip();
