                    .append("- Error: ")
                    .append(inert(f.error()))
                    .append(" | Fix: ")
                    .append(fix.isBlank() ? "(not recorded)" : fix)
                    .append(" (")
                    .append(f.count())
                    .append(" sessions)\n");
            }
        }

        sb.append("\nRECOMMENDATIONS FROM PRIOR ANALYSES:\n");
        if (p.recommendations().isEmpty()) {
            sb.append("- (none)\n");
        } else {
            for (NameCount r : p.recommendations()) {
                sb
                    .append("- ")
                    .append(inert(r.name()))
                    .append(" (")
                    .append(r.count())
                    .append(" sessions)\n");
            }
        }

        return sb.toString();
    }

