36	/** Serves the session list and transcripts from the shared store, keyed by {@code flavor}/source. */
37	@Controller("/api/brain")
38	public class BrainController {
39	
40	    private final SessionRepository sessions;
41	
42	    @Inject
43	    public BrainController(SessionRepository sessions) {
44	        this.sessions = sessions;
45	    }
46	
47	    /** Default page size when the client asks for none — enough to fill the sidebar in one load. */
48	    static final int DEFAULT_LIMIT = 200;
49	    /** Hard cap so a client can never make the store return an unbounded list in one response. */
50	    static final int MAX_LIMIT = 1000;
51	
52	    /**
53	     * One page of a source's sessions, newest first. The list is paged so a large store never has to
54	     * be returned (or rendered) all at once; the client loads more on demand and uses {@code total} to
55	     * know when it has them all.
56	     */
57	    @ExecuteOn(TaskExecutors.IO)
58	    @Get("/conversations")
59	    public ConversationPage listConversations(
60	        @QueryValue Optional<String> flavor,
61	        @QueryValue Optional<Integer> limit,
62	        @QueryValue Optional<Integer> offset
63	    ) {
64	        String source = flavor.orElse(AntigravityPaths.DEFAULT_FLAVOR);
65	        int pageLimit = clamp(limit.orElse(DEFAULT_LIMIT), 1, MAX_LIMIT);
66	        int pageOffset = Math.max(0, offset.orElse(0));
67	        List<Map<String, String>> items = sessions.listConversations(source, pageLimit, pageOffset);
68	        return new ConversationPage(items, sessions.countBySource(source), pageLimit, pageOffset);
69	    }
70	
71	    private static int clamp(int value, int min, int max) {
72	        return Math.max(min, Math.min(max, value));
73	    }
74	
75	    @ExecuteOn(TaskExecutors.IO)
76	    @Get(value = "/conversations/{id}/transcript", produces = "application/json")
77	    public String getTranscript(@PathVariable String id, @QueryValue Optional<String> flavor) {
78	        String steps = sessions.steps(flavor.orElse(AntigravityPaths.DEFAULT_FLAVOR), id);
79	        return steps != null ? steps : "[]";
80	    }
81	
82	    /**
83	     * Serves a referenced file's contents for the inline preview.
84	     *
85	     * <p>This one endpoint is inherently machine-local: Antigravity transcripts link to files under
86	     * the user's {@code ~/.gemini}, which live on the machine that ran the agent, not in the store. On
87	     * a different machine the file simply isn't there, and the preview returns not-found — the one
88	     * honest exception to reads coming from the store.
89	     */
90	    @ExecuteOn(TaskExecutors.IO)
91	    @Get(value = "/file", produces = "text/plain")
92	    public HttpResponse<String> getFileContent(@QueryValue String path) {
93	        try {
94	            Path filePath = Paths.get(path).normalize();
95	            Path geminiDir = AntigravityPaths.geminiRoot().normalize();
96	            if (!filePath.startsWith(geminiDir)) {
97	                return HttpResponse.unauthorized();
98	            }
99	            // Being inside the sandbox is not enough: the Gemini CLI keeps its own credentials in
100	            // this directory. Checked before the file is touched, so a refusal is not an existence
101	            // oracle for the rest of ~/.gemini.
102	            if (AntigravityPaths.isPreviewDenied(geminiDir, filePath)) {
103	                return deniedForPreview();
104	            }
105	            if (!Files.exists(filePath) || Files.isDirectory(filePath)) {
106	                return HttpResponse.notFound("File not available on this machine.");
107	            }
108	            // A symlink under ~/.gemini can point anywhere on disk; re-check the sandbox against the
109	            // fully resolved path so a planted link can't read files outside it — or, via the deny
110	            // check, reach a credential file that the requested spelling hid.
111	            Path realFile = filePath.toRealPath();
112	            Path realGeminiDir = geminiDir.toRealPath();
113	            if (!realFile.startsWith(realGeminiDir)) {
114	                return HttpResponse.unauthorized();
115	            }
116	            if (AntigravityPaths.isPreviewDenied(realGeminiDir, realFile)) {
117	                return deniedForPreview();
118	            }
119	            return HttpResponse.ok(Files.readString(realFile));
120	        } catch (NoSuchFileException e) {
121	            return HttpResponse.notFound("File not available on this machine.");
122	        } catch (IOException e) {
123	            return HttpResponse.serverError("Error reading file: " + e.getMessage());
124	        }
125	    }
126	
127	    /**
128	     * Forbidden rather than unauthorized: no credential makes these files previewable, and the
129	     * frontend's {@code apiFetch} prompts for an API token on a 401, which would send the user
130	     * hunting for a token that cannot help.
131	     */
132	    private static HttpResponse<String> deniedForPreview() {
133	        return HttpResponse
134	            .<String>status(HttpStatus.FORBIDDEN)
135	            .body("This file is not available for preview.");
136	    }
137	}

