// Targeted probe of the one semantic boundary the regex change touches.
//
// The old patterns used `\s*`, which crosses newlines; the replacements use `[ \t]*`, which does
// not. Random fragment mosaics are unlikely to land on that difference, so these cases are written
// to sit exactly on it: a metadata label whose value is on the *next* line, a status line preceded
// by blank lines, and combinations. If output differs, it differs here.

import { JSDOM } from "jsdom";
import { pathToFileURL } from "node:url";
import path from "node:path";

const dom = new JSDOM("<!doctype html><body></body>", { url: "http://localhost" });
globalThis.window = dom.window;
globalThis.document = dom.window.document;
globalThis.performance = dom.window.performance;
globalThis.Event = dom.window.Event;
globalThis.CustomEvent = dom.window.CustomEvent;
globalThis.Node = dom.window.Node;
globalThis.HTMLElement = dom.window.HTMLElement;
globalThis.requestIdleCallback = undefined;
globalThis.marked = { parse: (t) => `<md>${t}</md>` };
globalThis.DOMPurify = { sanitize: (h) => h };

const here = path.dirname(new URL(import.meta.url).pathname);
const baseline = await import(pathToFileURL(path.join(here, "timeline.baseline.js")).href);
const candidate = await import(pathToFileURL(path.join(here, "timeline.candidate.js")).href);

const CASES = [
  // The realistic shape: label and value on one line. Must be identical.
  "Created At: 2026-01-01T00:00:00Z\nCompleted At: 2026-01-01T00:00:05Z\nbody",
  "Created At: 2026-01-01T00:00:00Z\nThe command completed successfully.\noutput",
  "Created At: 2026-01-01T00:00:00Z\n  The command failed with exit code: 3\noutput",
  // The boundary: value on the NEXT line, which `\s*` used to reach across.
  "Created At:\n2026-01-01T00:00:00Z\nbody",
  "Created At:   \n   2026-01-01T00:00:00Z\nbody",
  "Completed At:\n2026-01-01T00:00:05Z\nbody",
  "Created At:\n\nCompleted At:\nvalue\nbody",
  "Encountered error in step execution:\nboom\nbody",
  // Status line preceded by blank lines, which `^\s*` used to swallow.
  "Created At: t\n\n\nThe command completed successfully.\nrest",
  "Created At: t\n\t\nThe command failed with exit code: 7\nrest",
  "Created At: t\nnoise\n\nThe command completed successfully.\ntail",
  // No metadata prefix at all, so the branch is not entered.
  "just some output\nThe command completed successfully.",
  // Tabs and wrapper labels, which later cleanup steps also touch.
  "Created At: t\n\t\tOutput:\nindented\n",
  '{"a":1}',
  "Created At: t\n" + JSON.stringify({ a: [1, 2, 3] }),
];

const TYPES = ["RUN_COMMAND", "FUNCTION_OUTPUT", "VIEW_FILE", "SEARCH_WEB", "USER_INPUT"];

function render(mod, steps) {
  const container = document.createElement("div");
  document.body.replaceChildren(container);
  mod.renderTranscript(steps, container);
  for (const h of container.querySelectorAll(".step-card .step-header")) h.click();
  return container.innerHTML;
}

let diverged = 0;
for (const content of CASES) {
  for (const type of TYPES) {
    const steps = [{ type, source: "MODEL", content, created_at: "2026-06-19T10:00:00Z" }];
    const a = render(baseline, steps);
    const b = render(candidate, steps);
    if (a !== b) {
      diverged++;
      console.log("DIVERGES  type=" + type + "  input=" + JSON.stringify(content));
      // Show just the differing region so the change is readable.
      let i = 0;
      while (i < Math.min(a.length, b.length) && a[i] === b[i]) i++;
      console.log("  baseline: ..." + JSON.stringify(a.slice(Math.max(0, i - 60), i + 120)));
      console.log("  candidate:..." + JSON.stringify(b.slice(Math.max(0, i - 60), i + 120)));
    }
  }
}
console.log(`${CASES.length * TYPES.length} edge cases, ${diverged} divergences`);

