39	// Transcript content is untrusted (it is whatever the agent, the user, or a web page the agent read
40	// happened to produce), so every piece of it that becomes HTML must pass through DOMPurify. The
41	// default allowed URI schemes are extended with file:// — Antigravity transcripts link local files
42	// that way and the click is intercepted for the in-app preview modal.
43	//
44	// DOMPurify's defaults stop scripts and event handlers, but they still allow several elements that
45	// markdown has no use for and that let transcript text reshape the page it is rendered into. A
46	// <style> block is not scoped to the transcript, so it can restyle or hide the application's own
47	// chrome; a <form> renders inside the trusted origin, which — next to the app's real "this server
48	// requires an API token" prompt — is enough to make a convincing one that posts the token elsewhere.
49	// Forbidding them costs nothing: none survives a markdown round-trip legitimately.
50	const PURIFY_CONFIG = {
51	  ALLOWED_URI_REGEXP:
52	    /^(?:(?:https?|mailto|file):|[^a-z]|[a-z+.\-]+(?:[^a-z+.\-:]|$))/i,
53	};
