55	/** Renders untrusted markdown to sanitized HTML. The only safe way to innerHTML transcript text. */
56	export function renderMarkdown(text) {
57	  if (text == null) return "";
58	  return DOMPurify.sanitize(marked.parse(String(text)), PURIFY_CONFIG);
59	}
