61	/**
62	 * fetch() for the app's own API. When the server guards the API with API_TOKEN, the token the user
63	 * entered is attached as a bearer; on a 401 the user is prompted once and the request retried, so a
64	 * freshly guarded server asks for the token instead of silently failing.
65	 */
66	export async function apiFetch(url, options = {}) {
67	  // localStorage can be unavailable (private browsing, test environments); degrade to promptless.
68	  const storage = {
69	    get() {
70	      try {
71	        return localStorage.getItem("agy-api-token") || "";
72	      } catch {
73	        return "";
74	      }
75	    },
76	    set(value) {
77	      try {
78	        localStorage.setItem("agy-api-token", value);
79	      } catch {}
80	    },
81	  };
82	  const doFetch = (token) => {
83	    const headers = { ...(options.headers || {}) };
84	    if (token) headers["Authorization"] = `Bearer ${token}`;
85	    return fetch(url, { ...options, headers });
86	  };
87	  let response = await doFetch(storage.get());
88	  if (response.status === 401) {
89	    const entered = window.prompt(
90	      "This server requires an API token (API_TOKEN). Enter it to continue:"
91	    );
92	    if (entered && entered.trim()) {
93	      storage.set(entered.trim());
94	      response = await doFetch(entered.trim());
95	    }
96	  }
97	  return response;
98	}
