33	/**
34	 * The analysis-quality eval harness: gathers a source's sessions via {@link SessionCollector}, grades
35	 * every session that already has a cached AI analysis with the deterministic {@link EvalScorer}, and
36	 * rolls the results into an {@link EvalReport} scoreboard.
37	 *
38	 * <p>The deterministic pass makes no LLM calls, so it is fast and reproducible; the report is
39	 * labelled with the active model so runs can be compared after a model/prompt change. When
40	 * {@code judge} is requested, an optional {@link AnalysisJudgeService} LLM pass additionally rates a
41	 * capped, parallelised sample of the analyses on a 1-5 rubric — degrading gracefully (rubric omitted
42	 * with an explanatory note) when AI is not configured or the model does not respond.
43	 */
44	@Singleton
45	public class EvalService {
46	
47	    private static final Logger LOG = LoggerFactory.getLogger(EvalService.class);
48	
49	    private static final int WORST_CASES = 10;
50	    /** Cap the (LLM) judged sample so the opt-in judge stays responsive on large histories. */
51	    static final int JUDGE_MAX_SESSIONS = 12;
52	    private static final int JUDGE_CONCURRENCY = 8;
53	    private static final int MAX_DIGEST_CHARS = 6000;
54	    private static final int MAX_ANALYSIS_CHARS = 6000;
55	
56	    /**
57	     * The judge is a panel: each session is rated once per lens and the verdicts are averaged. Since
58	     * the model runs at temperature 0, distinct lenses (not naive re-sampling) are what yield genuine
59	     * diversity, so a single harsh or lenient framing can't dominate the score.
60	     */
61	    static final List<String> JUDGE_LENSES = List.of(
62	        "a strict, skeptical reviewer who demands explicit evidence for every claim",
63	        "a fair, balanced reviewer weighing the analysis's strengths and weaknesses",
64	        "a pragmatic engineer judging whether the analysis would actually help a teammate"
65	    );
66	
67	    private static final ObjectMapper MAPPER = new ObjectMapper();
68	
69	    private final SessionCollector collector;
70	    private final AiConfig aiConfig;
71	    private final AnalysisJudgeService judgeService;
