79	        @Named(TaskExecutors.IO) ExecutorService executor
80	    ) {
81	        this.collector = collector;
82	        this.aiConfig = aiConfig;
83	        this.judgeService = judgeService;
84	        this.executor = executor;
85	    }
86	
87	    /** One evaluated session with everything the judge needs, kept alongside its graded result. */
88	    private record Judgeable(String id, String title, List<JsonNode> steps, JsonNode analysis) {}
89	
90	    public EvalReport forFlavor(String flavor, boolean judge) {
91	        SessionCollector.Collected collected = collector.collect(flavor);
92	
93	        List<EvalCaseResult> results = new ArrayList<>();
94	        List<Judgeable> judgeables = new ArrayList<>();
95	        for (FleetInsights.Session session : collected.sessions()) {
96	            JsonNode analysis = session.cachedSummary();
97	            if (analysis == null || analysis.isMissingNode() || analysis.isNull()) continue;
98	            String id = session.id() == null ? "unknown" : session.id();
99	            EvalCaseResult result = EvalScorer.score(id, session.steps(), analysis);
100	            results.add(result);
101	            judgeables.add(new Judgeable(id, result.title(), session.steps(), analysis));
102	        }
103	
104	        double avgScore = results.isEmpty()
105	            ? 0.0
106	            : round1(results.stream().mapToInt(EvalCaseResult::score).average().orElse(0.0));
107	
108	        List<NameCount> passRates = new ArrayList<>();
109	        for (String check : EvalScorer.checkNames()) {
110	            int passing = (int) results.stream().filter(r -> r.passed().contains(check)).count();
111	            passRates.add(new NameCount(check, passing));
112	        }
113	
114	        List<EvalCaseResult> worst = results
115	            .stream()
116	            .sorted(Comparator.comparingInt(EvalCaseResult::score))
117	            .limit(WORST_CASES)
118	            .toList();
119	
120	        return new EvalReport(
121	            flavor,
122	            collected.totalSessionCount(),
123	            collected.sessions().size(),
124	            results.size(),
125	            avgScore,
126	            modelLabel(),
127	            passRates,
128	            worst,
129	            runJudge(judge, judgeables)
130	        );
131	    }
132	
133	    private JudgeSummary runJudge(boolean requested, List<Judgeable> judgeables) {
