69	     * consolidation, so no IO-pool thread is parked just to sleep between ticks.
70	     */
71	    private final ScheduledExecutorService progressScheduler =
72	        Executors.newSingleThreadScheduledExecutor(runnable -> {
73	            Thread thread = new Thread(runnable, "analysis-progress-ticker");
74	            thread.setDaemon(true);
