    List<IngestFile> accepted = new ArrayList<>();
    for (IngestFile file : pushed.files()) {
        if (file == null || isBlank(file.path()) || file.content() == null) continue;
        if (accepted.size() >= MAX_FILES_PER_SESSION) {
