28	/**
29	 * Normalizes pushed trajectories and stores them.
30	 *
31	 * <p>The content hash is computed here, from the transcript the server actually received, rather than
32	 * trusted from the client. A client that hashed wrongly would otherwise be able to convince the store
33	 * that a changed trajectory was unchanged, and the row would never be refreshed. Getting it wrong now
34	 * costs only bandwidth: the client's manifest comparison misses, it re-pushes, and the upsert no-ops.
35	 */
36	@Singleton
37	public class Ingestor {
38	
39	    private static final Logger LOG = LoggerFactory.getLogger(Ingestor.class);
40	
