78	    /** Stores a batch, counting each trajectory as ingested, skipped (unchanged), or failed. */
79	    public IngestResult ingest(List<IngestSession> batch) {
80	        int ingested = 0;
81	        int skipped = 0;
82	        int failed = 0;
83	        for (IngestSession pushed : batch == null ? List.<IngestSession>of() : batch) {
84	            switch (store(pushed)) {
85	                case INGESTED -> ingested++;
86	                case SKIPPED -> skipped++;
87	                case FAILED -> failed++;
88	            }
89	        }
90	        return new IngestResult(ingested, skipped, failed);
91	    }
92	
93	    /**
94	     * Stores a batch of summaries pushed on their own (for sessions already in the store), counting
95	     * each as ingested, skipped (unchanged), or failed. Used for a summary that appeared after its
96	     * transcript was already ingested.
97	     */
98	    public IngestResult ingestSummaries(List<IngestSummary> batch) {
99	        int ingested = 0;
100	        int skipped = 0;
101	        int failed = 0;
102	        for (IngestSummary pushed : batch == null ? List.<IngestSummary>of() : batch) {
103	            switch (storeSummary(pushed)) {
104	                case INGESTED -> ingested++;
105	                case SKIPPED -> skipped++;
106	                case FAILED -> failed++;
