36	/** Serves the session list and transcripts from the shared store, keyed by {@code flavor}/source. */
37	@Controller("/api/brain")
38	public class BrainController {
39	
40	    private final SessionRepository sessions;
41	    private final SessionFileRepository sessionFiles;
42	
43	    @Inject
44	    public BrainController(SessionRepository sessions, SessionFileRepository sessionFiles) {
45	        this.sessions = sessions;
46	        this.sessionFiles = sessionFiles;
47	    }
48	
49	    /** Default page size when the client asks for none — enough to fill the sidebar in one load. */
50	    static final int DEFAULT_LIMIT = 200;
51	    /** Hard cap so a client can never make the store return an unbounded list in one response. */
52	    static final int MAX_LIMIT = 1000;
53	
54	    /**
55	     * One page of a source's sessions, newest first. The list is paged so a large store never has to
56	     * be returned (or rendered) all at once; the client loads more on demand and uses {@code total} to
57	     * know when it has them all.
58	     */
59	    @ExecuteOn(TaskExecutors.IO)
60	    @Get("/conversations")
61	    public ConversationPage listConversations(
62	        @QueryValue Optional<String> flavor,
63	        @QueryValue Optional<Integer> limit,
64	        @QueryValue Optional<Integer> offset
65	    ) {
66	        String source = flavor.orElse(AntigravityPaths.DEFAULT_FLAVOR);
67	        int pageLimit = clamp(limit.orElse(DEFAULT_LIMIT), 1, MAX_LIMIT);
68	        int pageOffset = Math.max(0, offset.orElse(0));
69	        List<Map<String, String>> items = sessions.listConversations(source, pageLimit, pageOffset);
70	        return new ConversationPage(items, sessions.countBySource(source), pageLimit, pageOffset);
71	    }
72	
73	    private static int clamp(int value, int min, int max) {
74	        return Math.max(min, Math.min(max, value));
75	    }
76	
77	    @ExecuteOn(TaskExecutors.IO)
78	    @Get(value = "/conversations/{id}/transcript", produces = "application/json")
79	    public String getTranscript(@PathVariable String id, @QueryValue Optional<String> flavor) {
80	        String steps = sessions.steps(flavor.orElse(AntigravityPaths.DEFAULT_FLAVOR), id);
81	        return steps != null ? steps : "[]";
82	    }
83	
84	    /**
85	     * Serves a referenced file's contents for the inline preview.
86	     *
87	     * <p>This one endpoint is inherently machine-local: Antigravity transcripts link to files under
88	     * the user's {@code ~/.gemini}, which live on the machine that ran the agent, not in the store. On
89	     * a different machine the file simply isn't there, and the preview returns not-found — the one
90	     * honest exception to reads coming from the store.
91	     */
92	    @ExecuteOn(TaskExecutors.IO)
93	    @Get(value = "/file", produces = "text/plain")
94	    public HttpResponse<String> getFileContent(
95	        @QueryValue String path,
96	        @QueryValue Optional<String> id,
97	        @QueryValue Optional<String> flavor
98	    ) {
99	        // Preferred path: the ingest client attached this file to the session, so it is in the store
100	        // and works from any machine. The server opens nothing, and the path is only a lookup key —
101	        // which is also why the sandbox and credential rules below do not apply to it: the client
102	        // that had the file decided what to send, and it applies its own secret filtering.
103	        if (id.isPresent()) {
104	            String source = flavor.orElse(AntigravityPaths.DEFAULT_FLAVOR);
105	            Optional<String> stored = sessionFiles.find(source, id.get(), path);
106	            if (stored.isPresent()) {
107	                return HttpResponse.ok(stored.get());
108	            }
109	        }
110	
111	        // Fallback for sessions ingested before attachments existed (or pushed with
112	        // --no-upload-files): read the server's own disk, sandboxed as before. This only ever works
113	        // when the machine serving the UI is the machine that ran the agent.
114	        try {
115	            Path filePath = Paths.get(path).normalize();
116	            Path geminiDir = AntigravityPaths.geminiRoot().normalize();
117	            if (!filePath.startsWith(geminiDir)) {
118	                return HttpResponse.unauthorized();
119	            }
120	            // Being inside the sandbox is not enough: the Gemini CLI keeps its own credentials in
121	            // this directory. Checked before the file is touched, so a refusal is not an existence
122	            // oracle for the rest of ~/.gemini.
123	            if (AntigravityPaths.isPreviewDenied(geminiDir, filePath)) {
124	                return deniedForPreview();
125	            }
126	            if (!Files.exists(filePath) || Files.isDirectory(filePath)) {
127	                return HttpResponse.notFound("File not available on this machine.");
128	            }
129	            // A symlink under ~/.gemini can point anywhere on disk; re-check the sandbox against the
130	            // fully resolved path so a planted link can't read files outside it — or, via the deny
131	            // check, reach a credential file that the requested spelling hid.
132	            Path realFile = filePath.toRealPath();
133	            Path realGeminiDir = geminiDir.toRealPath();
134	            if (!realFile.startsWith(realGeminiDir)) {
135	                return HttpResponse.unauthorized();
136	            }
137	            if (AntigravityPaths.isPreviewDenied(realGeminiDir, realFile)) {
138	                return deniedForPreview();
139	            }
140	            return HttpResponse.ok(Files.readString(realFile));
141	        } catch (NoSuchFileException e) {
142	            return HttpResponse.notFound("File not available on this machine.");
143	        } catch (IOException e) {
144	            return HttpResponse.serverError("Error reading file: " + e.getMessage());
145	        }
146	    }
147	
148	    /**
149	     * Forbidden rather than unauthorized: no credential makes these files previewable, and the
150	     * frontend's {@code apiFetch} prompts for an API token on a 401, which would send the user
151	     * hunting for a token that cannot help.
152	     */
153	    private static HttpResponse<String> deniedForPreview() {
154	        return HttpResponse
155	            .<String>status(HttpStatus.FORBIDDEN)
156	            .body("This file is not available for preview.");
157	    }
158	}

