16	package io.github.glaforge.agybrainviz;
17	
18	import jakarta.inject.Singleton;
19	import java.sql.Connection;
20	import java.sql.PreparedStatement;
21	import java.sql.ResultSet;
22	import java.sql.SQLException;
23	import java.util.List;
24	import java.util.Optional;
25	import javax.sql.DataSource;
26	
27	/**
28	 * Stores the files a transcript attached, keyed to the session that referenced them.
29	 *
30	 * <p>These exist so the inline preview can serve a file the machine running the UI has never seen.
31	 * Previously the preview read the server's own disk, which meant it worked only when the viewer and
32	 * the agent were the same machine — and, because the read was sandboxed to {@code ~/.gemini}, it did
33	 * not even work for the ordinary case of a project file attached to a prompt.
34	 */
35	@Singleton
36	public class SessionFileRepository {
37	
38	    private static final String UPSERT_SQL = """
39	        INSERT INTO session_files (source, session_id, path, content, updated_at)
40	        VALUES (?, ?, ?, ?, now())
41	        ON CONFLICT (source, session_id, path) DO UPDATE
42	           SET content = excluded.content,
43	               updated_at = now()
44	           WHERE session_files.content IS DISTINCT FROM excluded.content
45	        """;
46	
47	    private static final String FIND_SQL =
48	        "SELECT content FROM session_files WHERE source = ? AND session_id = ? AND path = ?";
49	
50	    private static final String DELETE_FOR_SESSION_SQL =
51	        "DELETE FROM session_files WHERE source = ? AND session_id = ?";
52	
53	    private final DataSource dataSource;
54	
55	    public SessionFileRepository(DataSource dataSource) {
56	        this.dataSource = dataSource;
57	    }
58	
59	    /**
60	     * Replaces the attachments recorded for one session.
61	     *
62	     * <p>Replace rather than merge: the transcript is the source of truth for which files it
63	     * references, so a file no longer mentioned after an edit should stop being served rather than
64	     * linger. Called inside the same push that stores the transcript.
65	     */
66	    public void replaceForSession(String source, String sessionId, List<IngestFile> files) {
67	        try (Connection conn = dataSource.getConnection()) {
68	            boolean previousAutoCommit = conn.getAutoCommit();
69	            conn.setAutoCommit(false);
70	            try {
71	                try (PreparedStatement delete = conn.prepareStatement(DELETE_FOR_SESSION_SQL)) {
72	                    delete.setString(1, source);
73	                    delete.setString(2, sessionId);
74	                    delete.executeUpdate();
75	                }
76	                if (!files.isEmpty()) {
77	                    try (PreparedStatement insert = conn.prepareStatement(UPSERT_SQL)) {
78	                        for (IngestFile file : files) {
79	                            insert.setString(1, source);
80	                            insert.setString(2, sessionId);
81	                            insert.setString(3, file.path());
82	                            insert.setString(4, file.content());
83	                            insert.addBatch();
84	                        }
85	                        insert.executeBatch();
86	                    }
87	                }
88	                conn.commit();
89	            } catch (SQLException e) {
90	                conn.rollback();
91	                throw e;
92	            } finally {
93	                conn.setAutoCommit(previousAutoCommit);
94	            }
95	        } catch (SQLException e) {
96	            throw new StoreUnavailableException(
97	                "Could not store the attached files for " + sessionId,
98	                e
99	            );
100	        }
101	    }
102	
103	    /** The stored content of one attached file, or empty when this session did not carry it. */
104	    public Optional<String> find(String source, String sessionId, String path) {
105	        try (
106	            Connection conn = dataSource.getConnection();
107	            PreparedStatement ps = conn.prepareStatement(FIND_SQL)
108	        ) {
109	            ps.setString(1, source);
110	            ps.setString(2, sessionId);
111	            ps.setString(3, path);
112	            try (ResultSet rs = ps.executeQuery()) {
113	                return rs.next() ? Optional.ofNullable(rs.getString(1)) : Optional.empty();
114	            }
115	        } catch (SQLException e) {
116	            throw new StoreUnavailableException(
117	                "Could not read the attached files for " + sessionId,
118	                e
119	            );
120	        }
121	    }
122	
123	    /** Removes a session's attachments, so deleting a session does not leave them behind. */
124	    public void deleteForSession(String source, String sessionId) {
125	        try (
126	            Connection conn = dataSource.getConnection();
127	            PreparedStatement ps = conn.prepareStatement(DELETE_FOR_SESSION_SQL)
128	        ) {
129	            ps.setString(1, source);
130	            ps.setString(2, sessionId);
131	            ps.executeUpdate();
132	        } catch (SQLException e) {
133	            throw new StoreUnavailableException(
134	                "Could not delete the attached files for " + sessionId,
135	                e
136	            );
137	        }
138	    }
139	}

